smart.css:
.smc-root {
  color: var(--smc-text, #1e293b);
  background: var(--smc-bg, #ffffff);
  font-family: var(--smc-font-body, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif);
  font-size: 16px;
  line-height: 1.75;
}

.smc-root h2,
.smc-root h3 {
  color: var(--smc-primary, #0f5b5d);
  font-family: var(--smc-font-heading, "Playfair Display", Georgia, serif);
  font-weight: 700;
  line-height: 1.35;
}

.smc-root h2 { font-size: clamp(22px, 3.2vw, 28px); margin: 0 0 16px; }
.smc-root h3 { font-size: 17.5px; margin: 0 0 8px; }
.smc-root p { margin: 0 0 14px; }
.smc-root a { color: var(--smc-accent, #c2410c); font-weight: 600; text-decoration: underline; }
.smc-root a:hover { color: var(--smc-primary, #0f5b5d); }

.smc-eyebrow {
  color: var(--smc-accent, #c2410c);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  margin: 0 0 8px;
}

.smc-intro {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 28px;
  padding: 30px 24px;
  background: color-mix(in srgb, var(--smc-primary, #0f5b5d) 7%, var(--smc-bg, #ffffff));
  border: 1px solid color-mix(in srgb, var(--smc-primary, #0f5b5d) 16%, var(--smc-border, #e2e8f0));
  border-radius: var(--smc-radius, 12px);
  margin-bottom: 36px;
}

.smc-intro-copy h2 { margin: 0 0 14px; }
.smc-intro-copy p:last-child { margin-bottom: 0; }
.smc-intro-media { margin: 0; }
.smc-intro-media img {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  border-radius: var(--smc-radius, 10px);
  box-shadow: 0 8px 24px rgba(0,0,0,0.08);
  cursor: zoom-in;
}
.smc-intro-media figcaption {
  color: var(--smc-muted, #64748b);
  font-size: 13.5px;
  line-height: 1.5;
  margin-top: 10px;
  text-align: center;
  font-style: italic;
}

.smc-section { padding: 40px 0 0; }
.smc-section-heading { max-width: 760px; margin-bottom: 24px; }
.smc-section-heading h2 { margin: 0 0 10px; }
.smc-section-heading p { color: var(--smc-muted, #64748b); margin: 0; }

.smc-feature-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 18px;
}

.smc-feature-card {
  padding: 24px;
  background: var(--smc-surface, #f8fafc);
  border: 1px solid var(--smc-border, #e2e8f0);
  border-radius: var(--smc-radius, 10px);
  transition: transform .2s ease, box-shadow .2s ease;
}

.smc-feature-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(0,0,0,0.05);
}

.smc-feature-number {
  display: inline-block;
  padding: 4px 12px;
  background: color-mix(in srgb, var(--smc-accent, #c2410c) 12%, var(--smc-bg, #ffffff));
  color: var(--smc-accent, #c2410c);
  border-radius: 999px;
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 12px;
}

.smc-feature-card h3 { margin: 0 0 8px; color: var(--smc-primary, #0f5b5d); }
.smc-feature-card p { color: var(--smc-muted, #475569); margin: 0; font-size: 15px; }

.smc-table-scroll {
  overflow-x: auto;
  margin: 24px 0 32px;
  border: 1px solid var(--smc-border, #cbd5e1);
  border-radius: var(--smc-radius, 10px);
  box-shadow: 0 4px 16px rgba(0,0,0,0.04);
}

.smc-compare-table {
  width: 100%;
  min-width: 620px;
  border-collapse: collapse;
  text-align: left;
  font-size: 14.5px;
  background: #ffffff;
}

.smc-compare-table th {
  background: var(--smc-primary, #0f5b5d);
  color: #ffffff;
  padding: 14px 18px;
  font-weight: 700;
  border: 1px solid var(--smc-primary, #0f5b5d);
}

.smc-compare-table td {
  padding: 13px 18px;
  border: 1px solid #e2e8f0;
  vertical-align: top;
}

.smc-compare-table tr:nth-child(even) td { background: #f8fafc; }
.smc-compare-table td.highlight { color: #0b5c66; font-weight: 700; background: #f0fdfa !important; }
.smc-compare-table td.warning { color: #dc2626; }

.smc-spec-wrap {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 28px;
  margin-top: 20px;
}

.smc-spec-media {
  margin: 0;
  padding: 14px;
  background: var(--smc-surface, #f8fafc);
  border: 1px solid var(--smc-border, #e2e8f0);
  border-radius: var(--smc-radius, 10px);
}

.smc-spec-media img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 8px;
  cursor: zoom-in;
}

.smc-spec-media figcaption {
  color: var(--smc-muted, #64748b);
  font-size: 13.5px;
  line-height: 1.5;
  margin-top: 10px;
  text-align: center;
  font-style: italic;
}

.smc-spec-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14.5px;
  border: 1px solid var(--smc-border, #e2e8f0);
  border-radius: 8px;
  overflow: hidden;
}

.smc-spec-table th,
.smc-spec-table td {
  padding: 12px 16px;
  border-bottom: 1px solid #e2e8f0;
  vertical-align: top;
}

.smc-spec-table th {
  background: color-mix(in srgb, var(--smc-primary, #0f5b5d) 10%, #ffffff);
  color: var(--smc-primary, #0f5b5d);
  font-weight: 700;
  width: 38%;
}

.smc-spec-table td { background: #ffffff; color: #334155; }
.smc-spec-table tr:last-child th,
.smc-spec-table tr:last-child td { border-bottom: 0; }

.smc-care-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 18px;
  margin: 24px 0 32px;
}

.smc-care-card {
  padding: 22px 24px;
  border-radius: var(--smc-radius, 10px);
}

.smc-care-card.pros {
  background: #f0fdf4;
  border: 1px solid #bbf7d0;
  border-left: 4px solid #16a34a;
}

.smc-care-card.cons {
  background: #fffbeb;
  border: 1px solid #fef3c7;
  border-left: 4px solid #f59e0b;
}

.smc-care-card h3 { margin: 0 0 10px; font-size: 16.5px; }
.smc-care-card.pros h3 { color: #166534; }
.smc-care-card.cons h3 { color: #92400e; }
.smc-care-card ul { margin: 0; padding-left: 20px; font-size: 14.5px; line-height: 1.65; }
.smc-care-card.pros li { color: #14532d; margin-bottom: 6px; }
.smc-care-card.cons li { color: #78350f; margin-bottom: 6px; }

.smc-faq { margin: 24px 0 36px; }
.smc-faq details {
  border: 1px solid var(--smc-border, #e2e8f0);
  border-radius: 8px;
  margin-bottom: 12px;
  background: var(--smc-surface, #f8fafc);
  overflow: hidden;
  transition: all .2s ease;
}

.smc-faq details[open] {
  background: #ffffff;
  border-color: color-mix(in srgb, var(--smc-primary, #0f5b5d) 30%, transparent);
  box-shadow: 0 4px 14px rgba(0,0,0,0.04);
}

.smc-faq summary {
  color: var(--smc-primary, #0f5b5d);
  font-family: var(--smc-font-heading, "Playfair Display", Georgia, serif);
  font-weight: 700;
  font-size: 16.5px;
  padding: 16px 20px;
  cursor: pointer;
  list-style: none;
}

.smc-faq summary::-webkit-details-marker { display: none; }
.smc-faq details p {
  padding: 0 20px 18px;
  color: #475569;
  margin: 0;
  font-size: 15px;
  line-height: 1.65;
}

.smc-brand-box {
  margin: 36px 0 18px;
  padding: 20px 24px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-left: 4px solid var(--smc-accent, #c2410c);
  border-radius: var(--smc-radius, 10px);
}

.smc-related-links-box {
  margin: 18px 0 24px;
  padding: 18px 22px;
  background: #f0fdfa;
  border: 1px solid #ccfbf1;
  border-radius: var(--smc-radius, 10px);
}

.smc-root.smc-js [data-smc-reveal] {
  opacity: 0;
  transform: translateY(14px);
  transition: opacity .45s ease, transform .45s ease;
}
.smc-root.smc-js [data-smc-reveal].is-visible { opacity: 1; transform: none; }

@container smc (min-width: 720px) {
  .smc-intro { grid-template-columns: 1.15fr .85fr; padding: 34px 28px; align-items: center; }
  .smc-feature-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .smc-spec-wrap { grid-template-columns: .9fr 1.1fr; align-items: start; }
  .smc-care-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@container smc (max-width: 440px) {
  .smc-root { font-size: 15px; }
  .smc-intro { padding: 20px 16px; }
  .smc-section { padding-top: 30px; }
}

