  background: var(--smc-surface, #f8fafc);
  border: 1px solid var(--smc-border, #e2e8f0);
  border-radius: var(--smc-radius, 10px);
  transition: transform .2s ease, box-shadow .2s ease;
}

.smc-feature-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(0,0,0,0.05);
}

.smc-feature-number {
  display: inline-block;
  padding: 4px 12px;
  background: color-mix(in srgb, var(--smc-accent, #c2410c) 12%, var(--smc-bg, #ffffff));
  color: var(--smc-accent, #c2410c);
  border-radius: 999px;
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 12px;
}

.smc-feature-card h3 { margin: 0 0 8px; color: var(--smc-primary, #0f5b5d); }
.smc-feature-card p { color: var(--smc-muted, #475569); margin: 0; font-size: 15px; }

.smc-table-scroll {
  overflow-x: auto;
  margin: 24px 0 32px;
  border: 1px solid var(--smc-border, #cbd5e1);
  border-radius: var(--smc-radius, 10px);
  box-shadow: 0 4px 16px rgba(0,0,0,0.04);
}

.smc-compare-table {
  width: 100%;
  min-width: 620px;
  border-collapse: collapse;
  text-align: left;
  font-size: 14.5px;
  background: #ffffff;
}

.smc-compare-table th {
  background: var(--smc-primary, #0f5b5d);
  color: #ffffff;
  padding: 14px 18px;
  font-weight: 700;
  border: 1px solid var(--smc-primary, #0f5b5d);
}

.smc-compare-table td {
  padding: 13px 18px;
  border: 1px solid #e2e8f0;
  vertical-align: top;
}

.smc-compare-table tr:nth-child(even) td { background: #f8fafc; }
.smc-compare-table td.highlight { color: #0b5c66; font-weight: 700; background: #f0fdfa !important; }
.smc-compare-table td.warning { color: #dc2626; }

.smc-spec-wrap {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 28px;
  margin-top: 20px;
}

.smc-spec-media {
  margin: 0;
  padding: 14px;
  background: var(--smc-surface, #f8fafc);
  border: 1px solid var(--smc-border, #e2e8f0);
  border-radius: var(--smc-radius, 10px);
}

.smc-spec-media img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 8px;
  cursor: zoom-in;
}

.smc-spec-media figcaption {
  color: var(--smc-muted, #64748b);
  font-size: 13.5px;
  line-height: 1.5;
  margin-top: 10px;
  text-align: center;
  font-style: italic;
}

.smc-spec-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14.5px;
  border: 1px solid var(--smc-border, #e2e8f0);
  border-radius: 8px;
  overflow: hidden;
}

.smc-spec-table th,
